pub const INTPTR_SIZE: u64 = 8;
pub const MAX_ALIGN_GUARANTEE: u64 = 8 * 16;
pub const BIN_HUGE: u64 = 73;
pub const BIN_FULL: u64 = BIN_HUGE + 1;
